mapper.select:
SELECT EXISTS (
  SELECT 1
  FROM profiles
  WHERE profile_id = #{profileId}
    AND deleted_at IS NULL
)

SELECT EXISTS (
  SELECT 1
  FROM profiles
  WHERE username = #{username}
    AND deleted_at IS NULL
)

SELECT EXISTS (
  SELECT 1
  FROM profiles
  WHERE phone_number = #{phoneNumber}
    AND deleted_at IS NULL
)

SELECT EXISTS (
  SELECT 1
  FROM profiles
  WHERE email = #{email}
    AND deleted_at IS NULL
)

SELECT EXISTS (
  SELECT 1
  FROM profiles
  WHERE phone_number = #{phoneNumber}
    AND profile_id != #{profileId}
    AND deleted_at IS NULL
)

SELECT EXISTS (
SELECT 1
FROM drinks
WHERE drink_id = #{drinkId}
AND deleted_at IS NULL
)
